import{_ as t,o,c as r,a2 as a}from"./chunks/framework.Cdp8-jB6.js";const u=JSON.parse('{"title":"Surface Hotspots Redesign — Visual Preview","description":"","frontmatter":{},"headers":[],"relativePath":"mockups/surface-redesign/README.md","filePath":"mockups/surface-redesign/README.md"}'),n={name:"mockups/surface-redesign/README.md"};function s(i,e,d,l,c,h){return o(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="surface-hotspots-redesign-—-visual-preview" tabindex="-1">Surface Hotspots Redesign — Visual Preview <a class="header-anchor" href="#surface-hotspots-redesign-—-visual-preview" aria-label="Permalink to &quot;Surface Hotspots Redesign — Visual Preview&quot;">​</a></h1><p><strong>Status:</strong> Slice 0 visual anchor for <a href="https://github.com/chipi/orrery/issues/283" target="_blank" rel="noreferrer">#283</a>. <strong>Generated by:</strong> <code>node scripts/mockups/render-surface-mockups.mjs</code><strong>Aspect:</strong> 1920 × 1080 PNG, full Orrery chrome + proposed UI.</p><p>These 12 mockups exist to anchor the redesign direction <em>before</em> any code or schema work begins. Each frame composites the proposed UI elements (rectangular region polygons, bounding-rect selection halos, scale-aware markers, flat-patch HUD, etc.) onto the actual planet textures from <code>static/textures/</code>. <strong>They are not photoreal app screenshots — they are schematic mockups in the Orrery design system.</strong></p><p>Re-run the script after design tweaks. The script and inline SVG templates are the source of truth.</p><h2 id="frames" tabindex="-1">Frames <a class="header-anchor" href="#frames" aria-label="Permalink to &quot;Frames&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>File</th><th>State</th></tr></thead><tbody><tr><td>01</td><td><code>01-mars-planet-wide.png</code></td><td>Mars planet wide · rectangular region polygons replace 3D-model + circular-ring markers</td></tr><tr><td>02</td><td><code>02-mars-mid-zoom-region.png</code></td><td>Mars mid-zoom · selection halo = bounding rectangle (no decoupled ring, no pulse)</td></tr><tr><td>03</td><td><code>03-mars-threshold-transition.png</code></td><td>Sphere → flat ground patch threshold · fade transition</td></tr><tr><td>04</td><td><code>04-mars-flatpatch-hud.png</code></td><td>Flat ground patch · CTX (regional) + HiRISE (detail) as true rectangles + traverse + waypoints + scale bar + lat/lon</td></tr><tr><td>05</td><td><code>05-mars-deep-zoom-markers.png</code></td><td>Deep zoom · markers at real-world scale (rover ≈ 6 px) · curated traverse stops · upsample-limit cue</td></tr><tr><td>06</td><td><code>06-mars-stationary.png</code></td><td>Stationary site (InSight) · single marker · no traverse polyline</td></tr><tr><td>07</td><td><code>07-moon-planet-wide.png</code></td><td>Moon planet wide · multi-agency rectangular regions (NASA / CNSA / JAXA / Roscosmos)</td></tr><tr><td>08</td><td><code>08-moon-mid-zoom-region.png</code></td><td>Moon mid-zoom · bounding-rect selection · explicit annotation of REMOVED elements (giant blue ring, pulse)</td></tr><tr><td>09</td><td><code>09-moon-threshold-transition.png</code></td><td>Moon sphere → flat patch threshold · lunar palette</td></tr><tr><td>10</td><td><code>10-moon-flatpatch-hud.png</code></td><td>Moon flat patch · LROC NAC ROI (regional) + LROC NAC detail + single Apollo 11 marker</td></tr><tr><td>11</td><td><code>11-moon-deep-zoom-markers.png</code></td><td>Moon deep zoom · LM at TRUE scale (4.3 m → 18 px) · annotated equipment · upsample-limit cue</td></tr><tr><td>12</td><td><code>12-moon-stationary-change.png</code></td><td>Hybrid CNSA site · Chang&#39;e 3 lander (1 marker) + Yutu rover short traverse</td></tr></tbody></table><h2 id="what-each-frame-is-meant-to-anchor" tabindex="-1">What each frame is meant to anchor <a class="header-anchor" href="#what-each-frame-is-meant-to-anchor" aria-label="Permalink to &quot;What each frame is meant to anchor&quot;">​</a></h2><ul><li><strong>01 / 07 — Planet wide.</strong> Multiple rectangular region polygons, agency-coloured borders, sit on the planet without occluding it the way 3D lander silhouettes do today. Labels with backdrop strips read against the surface texture. <em>Anchors:</em> the &quot;stop crowding the planet&quot; decision (current moon image 11 is over-stuffed) and the &quot;regions are the data shape&quot; decision.</li><li><strong>02 / 08 — Mid-zoom region selected.</strong> A single region polygon sits stylized on the curving sphere surface; its selection halo is a thin bounding rectangle pinned to the region itself, not a separately-floating ring. Microcopy (&quot;Zoom in to enter ground view ↓&quot;) signals the upcoming threshold transition. <em>Anchors:</em> fix for moon image 13 (decoupled halo) and explicit &quot;no pulse&quot; rule.</li><li><strong>03 / 09 — Threshold transition.</strong> The sphere fades out as the flat ground patch materializes below. <em>Anchors:</em> the architectural decision to abandon spherical-quad rendering in favour of a flat 2D patch at deep zoom. ADR-062 territory.</li><li><strong>04 / 10 — Flat patch open.</strong> Two rectangular layers (regional + detail) are honest about ground extent — labels show &quot;5 m/px · 10 × 6 km&quot; and &quot;25 cm/px · 500 × 300 m&quot;. Traverse polyline (Mars frame) goes from LANDING (SOL 0) to ROVER (SOL 5,045) with curated waypoint pins. Scale bar bottom-left, lat/lon bottom-right, &quot;← BACK TO PLANET&quot; top-left. <em>Anchors:</em> the entire flat-patch primitive — Slice 4.</li><li><strong>05 / 11 — Deep zoom.</strong> Markers are at <em>real</em> world scale. Rover on Mars ≈ 6 px; Apollo LM descent stage on moon ≈ 18 px. Annotation lines point to features at true scale (&quot;U.S. FLAG&quot;, &quot;RETROREFLECTOR&quot;). A vignette + microcopy (&quot;Approaching native pixel limit&quot;) tells the user the imagery isn&#39;t blurry — they&#39;ve zoomed past the data&#39;s resolving power. <em>Anchors:</em> the scale-aware marker rule (&quot;marker stays proportional and never gets bigger&quot;) and the upsample-warning rule.</li><li><strong>06 — Mars stationary.</strong> Single landing marker, no traverse, simpler HUD. <em>Anchors:</em> the &quot;stationary landings get exactly 1 marker&quot; rule.</li><li><strong>12 — Moon hybrid (Chang&#39;e 3 + Yutu).</strong> Lander gets one marker; rover traverse adds start + end markers along a short Q-curve path. <em>Anchors:</em> the rover-vs-stationary marker count distinction and explicit non-US-agency representation (CNSA red).</li></ul><h2 id="what-s-intentionally-not-here" tabindex="-1">What&#39;s intentionally NOT here <a class="header-anchor" href="#what-s-intentionally-not-here" aria-label="Permalink to &quot;What&#39;s intentionally NOT here&quot;">​</a></h2><ul><li><strong>Mobile layout.</strong> These are desktop mockups. Mobile-specific HUD reflow ships in Slice 6.</li><li><strong>i18n.</strong> Strings are EN-only. Translation pass is Slice 6.</li><li><strong>Real terrain at the right resolution.</strong> Backgrounds are 2K planet textures and pattern fills, not actual CTX/HiRISE/LROC tiles. The mockups encode <em>layout intent</em>, not data fidelity.</li><li><strong>Pixel-precise positions.</strong> Region rectangles are placed where the missions roughly are on the texture, but they&#39;re not lat/lon-projected. Slice 1 backfills the real <code>region_bounds</code> per site.</li></ul><h2 id="iterating" tabindex="-1">Iterating <a class="header-anchor" href="#iterating" aria-label="Permalink to &quot;Iterating&quot;">​</a></h2><p>To tweak the design, edit <code>scripts/mockups/render-surface-mockups.mjs</code> (frame template functions) and re-run:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>node scripts/mockups/render-surface-mockups.mjs</span></span></code></pre></div><p>The Orrery design tokens are mirrored at the top of the script (<code>T = { bg, accent, teal, mars, nasa, ... }</code>); keep them in sync with <code>src/lib/styles/tokens.css</code> when those drift.</p>',14)])])}const m=t(n,[["render",s]]);export{u as __pageData,m as default};
